/**
 * Build the self-contained VM runner bundle (Stage 3 / S3c).
 *
 * Produces a single CJS file the Freestyle VM runs as
 *   node run-in-vm.cjs --repo-root /work --question "…" --emit-json
 * with no node_modules and no web-ade source tree present. Two steps:
 *
 *   1. Embed `opencode-assets/.opencode/tool/emit_trail.ts` as a string
 *      constant (`emit-trail-asset.generated.ts`) so the bundle can write the
 *      tool into the cloned checkout itself (opencode discovers it there).
 *   2. esbuild `core/run.ts` → `.vm-dist/run-in-vm.cjs`, bundling every dep
 *      (incl. `@opencode-ai/sdk`, `validatePayload` + its `alexandria` dep).
 *      Node built-ins stay external; opencode is the only runtime the VM must
 *      already have (baked into the base snapshot).
 *
 * Run: `node src/lib/authoring/core/build-vm-bundle.mjs` (or `npm run build:authoring-vm`).
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const here = path.dirname(fileURLToPath(import.meta.url)); // …/src/lib/authoring/core
const authoringRoot = path.dirname(here); // …/src/lib/authoring

const assetPath = path.join(
  authoringRoot,
  'opencode-assets/.opencode/tool/emit_trail.ts'
);
const genPath = path.join(here, 'emit-trail-asset.generated.ts');
const outFile = path.join(authoringRoot, '.vm-dist/run-in-vm.cjs');

// 1. Embed the emit_trail tool source. JSON.stringify handles all escaping.
const assetSrc = readFileSync(assetPath, 'utf8');
const banner =
  '// GENERATED by core/build-vm-bundle.mjs — do not edit by hand.\n' +
  '// Embeds opencode-assets/.opencode/tool/emit_trail.ts so the VM bundle\n' +
  '// is self-contained (no source tree needed at runtime).\n';
writeFileSync(
  genPath,
  `${banner}export const EMIT_TRAIL_SOURCE = ${JSON.stringify(assetSrc)};\n`,
  'utf8'
);
console.log(`embedded emit_trail asset → ${path.relative(process.cwd(), genPath)}`);

// 2. Bundle the runner.
mkdirSync(path.dirname(outFile), { recursive: true });
await build({
  entryPoints: [path.join(here, 'run.ts')],
  outfile: outFile,
  bundle: true,
  platform: 'node',
  format: 'cjs',
  target: 'node20',
  logLevel: 'info',
  // Node built-ins are provided by the VM's node; everything else is inlined.
});
console.log(`bundled runner → ${path.relative(process.cwd(), outFile)}`);
